// Usuario autenticado: el Webhook ya verificó el JWT (credencial JWT Auth account)
const input = $input.first().json;
const userId = input.jwtPayload?.userId ?? input.jwtPayload?.sub;
if (!userId) throw new Error('userId no encontrado en el token');

const body = input.body || {};
const domain = String(body.domain || '');
const DOMAINS = {
  lab_orders: { system: "Interpretás comandos de voz del equipo de una clínica odontológica dentro de Invoke IA.\nRecibís una frase dictada (puede venir con errores del reconocimiento de voz) y devolvés SOLO un objeto JSON, sin texto alrededor ni bloques de código.\n\nINTENTS\n- \"lab_order.move\": mover una orden de laboratorio existente (se nombra su número) a otra etapa. Ej.: \"la 45 ya la mandamos ayer\", \"la orden cuarenta y cinco volvió del laboratorio\".\n- \"lab_order.open\": abrir / mostrar una orden existente por su número.\n- \"lab_order.create\": crear una orden de laboratorio nueva para un paciente.\n- \"lab_order.update\": cambiar algo de una orden existente (con número): la fecha de entrega (due_date), marcarla o desmarcarla urgente (urgent_change) o agregarle una nota (note_add). Ej.: \"la 45 la entregan el lunes\", \"la 45 ya no es urgente\", \"anotale a la 45 color A2\".\n- \"lab_order.status\": preguntar cómo está una orden existente (con número): etapa, entrega. Ej.: \"¿en qué anda la 45?\".\n- \"lab_order.list\": ver un grupo de órdenes en la pantalla. Ej.: \"mostrame las atrasadas\", \"¿cuántas urgentes hay?\", \"las de Ana Pérez\", \"las de Dental Sur\", \"en el tablero\", \"sacá los filtros\".\n- \"lab_order.edit\": editar una orden existente (con número) en otra cosa que la entrega, lo urgente o una nota: sus trabajos, piezas, cantidad, descripción, laboratorio o paciente, o pedir abrirla para editarla. Lo que se pide cambiar va en draft_edit (regla 9; vacío si solo se pidió editarla). Ej.: \"editá la 45\", \"a la 45 agregale un perno en la 21\", \"a la 45 sacale la corona\", \"la 45 es para María López\", \"la 45 va al laboratorio Dental Sur\".\n- \"lab_order.draft_edit\": SOLO cuando viene ORDEN EN CREACIÓN u ORDEN EN EDICIÓN: la frase corrige esa orden. Ej.: \"que sea urgente\", \"agregá un perno en la 21\", \"sacá la corona\", \"la corona es en la 46\", \"que sean dos\", \"es para María López\", \"al laboratorio Dental Sur\", \"no la envíes\", \"entrega el viernes\".\n- \"unknown\": cualquier otra cosa, o si no estás seguro.\n\nSi viene ORDEN EN CREACIÓN u ORDEN EN EDICIÓN, el intent es \"lab_order.draft_edit\" o \"unknown\" (nunca otro).\n\nREGLAS\n1. Usá SOLO ids de ETAPAS y LABORATORIOS que estén en las listas. Si no coincide con ninguno, null. Nunca inventes ids.\n2. Fechas en formato YYYY-MM-DD calculadas desde FECHA DE HOY (\"ayer\", \"el lunes\" pasado, \"el viernes\" próximo, \"en una semana\").\n   - effective_date: cuándo PASÓ el movimiento (\"se envió ayer\"). Nunca futura. null si no se dijo.\n   - due_date: la entrega prometida por el laboratorio (\"entrega el viernes\"). null si no se dijo.\n3. move_kind: \"send\" (se envió/mandó al laboratorio), \"received\" (llegó/volvió a la clínica), \"complete\" (se terminó/entregó/colocó al paciente), \"cancel\" (se canceló/anuló), \"next\" (siguiente etapa) o null. Si se nombra una etapa, poné su id en stage_id.\n4. Para crear: patient = el nombre del paciente tal como se dijo (sin inventar apellidos); items = cada trabajo con service (nombre del trabajo como se dijo, ej. \"corona de zirconio\"), quantity (1 si no se dijo) y teeth (piezas en notación FDI: 11–48, 51–85; \"la treinta y seis\" = 36). teeth (afuera de items) = piezas generales si no se asocian a un trabajo. send = true solo si se pidió enviarla ya al laboratorio. is_urgent = true solo si se dijo urgente. notes = indicaciones extra (color, observaciones) o null.\n5. order_id = el número de orden dicho (los números pueden venir en palabras). Para crear, null.\n6. lab_order.update: urgent_change = true (marcar urgente), false (quitar urgente) o null; note_add = el texto de la nota tal como se dictó o null; due_date si cambia la entrega. Lo que no se pidió, en null.\n7. lab_order.list: filter = {\"overdue\":bool,\"urgent\":bool,\"due_today\":bool,\"view\":\"list\"|\"board\"|null,\"clear\":bool,\"count\":bool}. count = true si se preguntó cuántas. Si se nombra un paciente va en patient; un laboratorio, su id en laboratory_id. En los demás intents filter = null.\n8. confidence entre 0 y 1: qué tan seguro estás del intent y los datos. Si la frase es ambigua, confidence < 0.5.\n9. lab_order.draft_edit y lab_order.edit: draft_edit = {\"patient\":null,\"add_items\":[],\"remove_items\":[],\"update_items\":[],\"work_description\":null,\"laboratory_id\":null,\"clear_laboratory\":false,\"send\":null,\"due_date\":null,\"urgent\":null,\"note_add\":null} con SOLO lo que se pidió cambiar:\n   - patient: otro paciente (nombre tal como se dijo).\n   - add_items: trabajos nuevos [{service, quantity, teeth}] como en la regla 4.\n   - remove_items: nombres de los trabajos a quitar, tal como figuran en la orden.\n   - update_items: [{service, quantity, teeth}] para cambiar cantidad o piezas de un trabajo que ya está (service = su nombre en la orden; null si hay uno solo o si son las piezas generales). Lo que no cambia, null.\n   - work_description: nueva descripción libre del trabajo (reemplaza la anterior).\n   - laboratory_id: id del laboratorio nombrado; clear_laboratory = true si se pidió sacarlo.\n   - send: true (enviarla al crearla), false (no enviarla) o null. due_date: nueva entrega (en la creación implica enviarla).\n   - En una ORDEN EN EDICIÓN (o con lab_order.edit) la orden ya existe: send siempre null; due_date solo cambia la entrega.\n   - urgent: true / false / null. note_add: texto a agregar a las notas.\n   En los demás intents draft_edit = null.\n\nFORMATO (todas las claves siempre):\n{\"intent\":\"...\",\"order_id\":null,\"stage_id\":null,\"move_kind\":null,\"effective_date\":null,\"due_date\":null,\"laboratory_id\":null,\"patient\":null,\"items\":[],\"work_description\":null,\"teeth\":[],\"is_urgent\":false,\"send\":false,\"notes\":null,\"urgent_change\":null,\"note_add\":null,\"filter\":null,\"draft_edit\":null,\"confidence\":0.0}", prepare: (ctx, body) => {
  const stages = (Array.isArray(ctx.stages) ? ctx.stages : []).slice(0, 40)
    .map(s => ({ id: Number(s && s.id), name: String((s && s.name) || '').slice(0, 80), kind: String((s && s.kind) || '') }))
    .filter(s => Number.isInteger(s.id) && s.name);
  const laboratories = (Array.isArray(ctx.laboratories) ? ctx.laboratories : []).slice(0, 80)
    .map(l => ({ id: String((l && l.id) || ''), name: String((l && l.name) || '').slice(0, 80) }))
    .filter(l => l.id && l.name);
  // Orden abierta por voz, nueva o en edición (sin el paciente): la frase es una corrección.
  const d = ctx.draft && typeof ctx.draft === 'object' ? ctx.draft : null;
  const editing = Boolean(d && d.mode === 'edit');
  const short = (v, max) => String(v == null ? '' : v).slice(0, max);
  const draftLines = d ? [
    '',
    editing
      ? 'ORDEN EN EDICIÓN n.º ' + (Number(d.order_id) || '?') + ', etapa ' + (short(d.stage, 80) || '?') + ' (ya existe; la frase la corrige):'
      : 'ORDEN EN CREACIÓN (la frase la corrige):',
    '- Trabajos: ' + ((Array.isArray(d.items) ? d.items : []).slice(0, 10)
      .map(i => short(i && i.service, 80) + ' x' + (Number(i && i.quantity) || 1) + (Array.isArray(i && i.teeth) && i.teeth.length ? ' (piezas ' + i.teeth.slice(0, 32).join(', ') + ')' : ''))
      .join('; ') || '(ninguno)'),
    '- Piezas generales: ' + ((Array.isArray(d.teeth) ? d.teeth.slice(0, 32).join(', ') : '') || '(ninguna)'),
    '- Descripción: ' + (short(d.work_description, 300) || '(ninguna)'),
    '- Laboratorio: ' + (short(d.laboratory, 80) || '(ninguno)'),
    editing
      ? '- Entrega: ' + (short(d.due_date, 10) || '(sin fecha)')
      : '- Enviar al crear: ' + (d.send === true ? 'sí, entrega ' + short(d.due_date, 10) : 'no'),
    '- Urgente: ' + (d.is_urgent === true ? 'sí' : 'no'),
    '- Notas: ' + (short(d.notes, 300) || '(ninguna)'),
  ] : [];
  return {
    lines: [
      '',
      'ETAPAS (id · nombre · tipo):',
      stages.map(s => '- ' + s.id + ' · ' + s.name + ' · ' + s.kind).join('\n') || '(ninguna)',
      '',
      'LABORATORIOS (id · nombre):',
      laboratories.map(l => '- ' + l.id + ' · ' + l.name).join('\n') || '(ninguno)',
      ...draftLines,
    ],
    meta: { stages, laboratories, hasDraft: Boolean(d), editing },
  };
} },
  perio: { system: "Interpretás lo que dicta un profesional mientras sondea un periodontograma en Invoke IA.\nRecibís una frase (puede venir con errores del reconocimiento de voz, en español o inglés) y el estado de la sonda, y devolvés SOLO un objeto JSON, sin texto alrededor ni bloques de código.\n\nTraducís la frase a COMANDOS, en el orden en que se dijeron. Solo reformulás: nunca agregues valores, piezas ni marcas que no estén en la frase. Si no hay nada que se pueda expresar, commands = [].\n\nCOMANDOS\n- {\"kind\":\"values\",\"values\":[3,2,4]}: valores en la línea activa, un sitio tras otro (la sonda avanza sola). Enteros de -10 a 15, tal como se dijeron (\"menos 2\" = -2). Los tres sitios de una cara van distal, centro, mesial.\n- {\"kind\":\"goto\",\"tooth\":38,\"side\":\"i\",\"sites\":[0],\"line\":\"ps\"}: ir a una pieza, cara, sitios y/o línea; todas las claves son opcionales pero al menos una. side: \"v\" (vestibular/bucal) o \"i\" (lingual/palatino). sites: 0 distal, 1 centro, 2 mesial. line: \"ps\" (profundidad), \"mg\" (margen gingival / recesión), \"bop\" (sangrado, SS), \"sup\" (supuración), \"plaque\" (placa).\n- {\"kind\":\"flag\",\"flag\":\"bop\",\"on\":true,\"tooth\":16,\"side\":\"v\",\"sites\":[2]}: marcar (on true) o quitar (on false) sangrado (\"bop\"), supuración (\"sup\") o placa (\"plaque\"). Sin pieza va al último sitio medido; sin sitios, a ese sitio o a los tres de la pieza dicha.\n- {\"kind\":\"neighbour\",\"delta\":1}: pieza siguiente (1) o anterior (-1).\n- {\"kind\":\"pass\",\"pass\":\"mg\"}: cambiar de pasada: \"ps\" profundidad, \"mg\" margen gingival, \"fm\" furcas y movilidad.\n- {\"kind\":\"focus\",\"focus\":\"L\"}: qué arcada mostrar: \"U\" superior, \"L\" inferior, \"both\" ambas, \"auto\" seguir a la sonda.\n- {\"kind\":\"mobility\",\"tooth\":46,\"value\":1}: movilidad 0 a 3 (pieza opcional: sin ella, la actual).\n- {\"kind\":\"furcation\",\"tooth\":36,\"entry\":\"v\",\"grade\":2}: furca 0 a 3; entry \"v\" vestibular, \"l\" lingual, \"mp\" mesiopalatina, \"dp\" distopalatina (opcionales).\n- {\"kind\":\"answer\",\"on\":true}: \"sí\" / \"no\" en una línea de marcas (marca o deja limpio el sitio y avanza).\n- {\"kind\":\"same\"}: \"igual que antes\" (el valor del examen anterior).\n- {\"kind\":\"undo\"}, {\"kind\":\"redo\"}, {\"kind\":\"delete\"}: deshacer, rehacer, borrar el último valor.\n- {\"kind\":\"status\",\"tooth\":18,\"status\":\"missing\"}: estado de una pieza: \"present\", \"missing\" (ausente, extraída), \"implant\" o \"pontic\". La pantalla pregunta antes de cambiarlo.\n- {\"kind\":\"copy\",\"what\":\"all\"}: llenar lo vacío con el examen anterior: \"all\", \"ps\" (profundidad), \"mg\" (margen), \"fm\" (furcas y movilidad). La pantalla pregunta antes.\n- {\"kind\":\"query\",\"what\":\"previous\",\"tooth\":16}: una pregunta, no escribe nada: \"previous\" (qué tenía en el examen anterior), \"current\" (qué tiene ahora, \"leeme el 16\"), \"missing\" (qué falta sondar). tooth opcional (sin ella, la pieza de la sonda).\nConfirmar, descartar o parar el dictado NO son comandos que puedas devolver.\n\nREGLAS\n1. Piezas en notación FDI de dos dígitos (11 a 48). Si se nombra la pieza por su nombre (\"primer molar inferior izquierdo\"), convertila (36), pero bajá confidence a 0.7 o menos.\n2. Usá el ESTADO DE LA SONDA: \"el de al lado\" = neighbour; \"por palatino\" / \"del otro lado\" = goto con side; \"ahora el margen\" = pass mg. No muevas la sonda si la frase no lo pide.\n3. Valores en la línea activa salvo que la frase nombre otra pieza, cara o línea (entonces primero un goto).\n4. Recesión: si \"RECESIÓN NEGATIVA\" es sí, la clínica dice la recesión como \"menos N\"; copiá los valores tal como se dijeron, el sistema los convierte.\n5. confidence entre 0 y 1: qué tan seguro estás de los comandos. Si la frase es ambigua o no es un dictado del periodontograma, confidence < 0.5 y commands = [].\n\nEJEMPLOS\n\"en el treinta y ocho por lingual tengo tres, dos y cuatro y le sangra el distal\" → {\"commands\":[{\"kind\":\"goto\",\"tooth\":38,\"side\":\"i\"},{\"kind\":\"values\",\"values\":[3,2,4]},{\"kind\":\"flag\",\"flag\":\"bop\",\"on\":true,\"sites\":[0]}],\"confidence\":0.95}\n\"the lower left first molar buccal is four three five\" → {\"commands\":[{\"kind\":\"goto\",\"tooth\":36,\"side\":\"v\"},{\"kind\":\"values\",\"values\":[4,3,5]}],\"confidence\":0.7}\n\"bueno, ahora pasemos al margen\" → {\"commands\":[{\"kind\":\"pass\",\"pass\":\"mg\"}],\"confidence\":0.9}\n\"esperá que atiendo el teléfono\" → {\"commands\":[],\"confidence\":0.1}\n\nFORMATO: {\"commands\":[...],\"confidence\":0.0}", prepare: (ctx) => {
  const list = v => (Array.isArray(v) ? v : []).map(Number).filter(n => Number.isInteger(n) && n >= 11 && n <= 48).slice(0, 32);
  const teeth = ctx.teeth && typeof ctx.teeth === 'object' ? ctx.teeth : {};
  const c = ctx.cursor && typeof ctx.cursor === 'object' ? ctx.cursor : null;
  const pass = ['ps', 'mg', 'fm'].includes(ctx.pass) ? ctx.pass : 'ps';
  const line = ['value', 'bop', 'sup', 'plaque'].includes(ctx.line) ? ctx.line : 'value';
  const PASS = { ps: 'profundidad', mg: 'margen gingival', fm: 'furcas y movilidad' };
  const LINE = { value: pass === 'mg' ? 'valores de margen gingival' : 'valores de profundidad', bop: 'marcas de sangrado (SS)', sup: 'marcas de supuración', plaque: 'marcas de placa' };
  const where = c && Number.isInteger(Number(c.tooth))
    ? 'pieza ' + Number(c.tooth) + ', cara ' + (c.side === 'v' ? 'vestibular' : 'lingual/palatina') + ', sitio ' + String(c.site || '').slice(0, 10)
    : '(sin sonda)';
  return {
    lines: [
      '',
      'ESTADO DE LA SONDA:',
      '- Pasada: ' + PASS[pass],
      '- Línea activa: ' + (pass === 'fm' ? 'movilidad de la pieza ' + (Number(ctx.fm_tooth) || '?') : LINE[line]),
      '- Sonda en: ' + where,
      '- Vista: ' + String(ctx.focus || 'auto').slice(0, 6),
      '- Piezas presentes: ' + (list(teeth.present).join(', ') || '(ninguna)'),
      '- Implantes: ' + (list(teeth.implants).join(', ') || '(ninguno)'),
      '- Ausentes: ' + (list(teeth.missing).join(', ') || '(ninguna)'),
      '- Pónticos: ' + (list(teeth.pontics).join(', ') || '(ninguno)'),
      '- Solo implantes: ' + (ctx.implants_only === true ? 'sí' : 'no'),
      '- RECESIÓN NEGATIVA: ' + (ctx.margin_negative === true ? 'sí' : 'no'),
    ],
    meta: {},
  };
} },
};
const mod = Object.prototype.hasOwnProperty.call(DOMAINS, domain) ? DOMAINS[domain] : null;
if (!mod) throw new Error('Módulo de voz desconocido: ' + domain);
const text = String(body.text || '').trim().slice(0, 500);
if (!text) throw new Error('Falta la frase (text)');
const today = /^\d{4}-\d{2}-\d{2}$/.test(String(body.today)) ? String(body.today) : new Date().toISOString().slice(0, 10);
const ctx = body.context && typeof body.context === 'object' ? body.context : {};
const built = mod.prepare(ctx, body);

const prompt = [
  'FECHA DE HOY: ' + today + ' (' + String(body.weekday || '').slice(0, 20) + '), zona horaria ' + String(body.timezone || '').slice(0, 60),
  'IDIOMA: ' + String(body.locale || 'es').slice(0, 10),
  'PANTALLA: ' + String(body.route || '/').slice(0, 120),
  ...built.lines,
  '',
  'FRASE: ' + JSON.stringify(text),
].join('\n');

return [{ json: { userId, domain, text, today, meta: built.meta, systemPrompt: mod.system, prompt } }];

const q = $('Preparar Consulta').first().json;
const raw = String($input.first().json.output ?? '');
let p = {};
try {
  p = JSON.parse(raw.replace(/^\s*```(json)?\s*/i, '').replace(/```\s*$/, '').trim());
} catch (_) {
  p = {};
}
if (!p || typeof p !== 'object') p = {};

const VALIDATE = {
  lab_orders: (p, m, today) => {
  // Lista cerrada: solo ids que mandó el frontend, fechas válidas y piezas FDI.
  const INTENTS = ['lab_order.move', 'lab_order.create', 'lab_order.open', 'lab_order.update', 'lab_order.status', 'lab_order.list', 'lab_order.draft_edit', 'lab_order.edit', 'unknown'];
  const KINDS = ['send', 'received', 'complete', 'cancel', 'next'];
  const stageIds = new Set(m.stages.map(s => s.id));
  const labIds = new Set(m.laboratories.map(l => l.id));
  const isDate = v => typeof v === 'string' && /^\d{4}-\d{2}-\d{2}$/.test(v) && !Number.isNaN(Date.parse(v));
  const str = (v, max) => (typeof v === 'string' && v.trim() ? v.trim().slice(0, max) : null);
  const isTooth = n => Number.isInteger(n) && ((n >= 11 && n <= 48 && n % 10 >= 1 && n % 10 <= 8) || (n >= 51 && n <= 85 && n % 10 >= 1 && n % 10 <= 5));
  const teeth = v => [...new Set((Array.isArray(v) ? v : []).map(Number).filter(isTooth))].slice(0, 32);

  const intent = INTENTS.includes(p.intent) ? p.intent : 'unknown';
  const orderId = Number(p.order_id);
  const stageId = Number(p.stage_id);
  const effective = isDate(p.effective_date) && p.effective_date <= today ? p.effective_date : null;
  const toItems = v => (Array.isArray(v) ? v : []).slice(0, 10)
    .map(i => ({ service: str(i && i.service, 80), quantity: Math.min(99, Math.max(1, Math.round(Number(i && i.quantity)) || 1)), teeth: teeth(i && i.teeth) }))
    .filter(i => i.service);
  const items = toItems(p.items);
  const confidence = Number(p.confidence);
  const bool = v => (typeof v === 'boolean' ? v : null);
  const de = p.draft_edit && typeof p.draft_edit === 'object' ? p.draft_edit : null;
  const draftEdit = de ? {
    patient: str(de.patient, 80),
    add_items: toItems(de.add_items),
    remove_items: (Array.isArray(de.remove_items) ? de.remove_items : []).map(v => str(v, 80)).filter(Boolean).slice(0, 10),
    update_items: (Array.isArray(de.update_items) ? de.update_items : []).slice(0, 10).map(i => {
      const qty = Math.round(Number(i && i.quantity));
      return {
        service: str(i && i.service, 80),
        quantity: i && i.quantity != null && Number.isFinite(qty) ? Math.min(99, Math.max(1, qty)) : null,
        teeth: i && Array.isArray(i.teeth) ? teeth(i.teeth) : null,
      };
    }).filter(i => i.quantity !== null || i.teeth !== null),
    work_description: str(de.work_description, 500),
    laboratory_id: typeof de.laboratory_id === 'string' && labIds.has(de.laboratory_id) ? de.laboratory_id : null,
    clear_laboratory: de.clear_laboratory === true,
    // Una orden que ya existe no se envía desde acá (se mueve de etapa).
    send: m.editing || intent === 'lab_order.edit' ? null : bool(de.send),
    due_date: isDate(de.due_date) && de.due_date >= today ? de.due_date : null,
    urgent: bool(de.urgent),
    note_add: str(de.note_add, 500),
  } : null;

  const result = {
    intent,
    order_id: Number.isInteger(orderId) && orderId > 0 ? orderId : null,
    stage_id: stageIds.has(stageId) ? stageId : null,
    move_kind: KINDS.includes(p.move_kind) ? p.move_kind : null,
    effective_date: effective,
    due_date: isDate(p.due_date) ? p.due_date : null,
    laboratory_id: typeof p.laboratory_id === 'string' && labIds.has(p.laboratory_id) ? p.laboratory_id : null,
    patient: str(p.patient, 80),
    items,
    work_description: str(p.work_description, 500),
    teeth: teeth(p.teeth),
    is_urgent: p.is_urgent === true,
    send: p.send === true,
    notes: str(p.notes, 500),
    urgent_change: typeof p.urgent_change === 'boolean' ? p.urgent_change : null,
    note_add: str(p.note_add, 500),
    filter: p.filter && typeof p.filter === 'object' ? {
      overdue: p.filter.overdue === true,
      urgent: p.filter.urgent === true,
      due_today: p.filter.due_today === true,
      view: p.filter.view === 'list' || p.filter.view === 'board' ? p.filter.view : null,
      clear: p.filter.clear === true,
      count: p.filter.count === true,
    } : null,
    draft_edit: intent === 'lab_order.draft_edit' || intent === 'lab_order.edit' ? draftEdit : null,
    confidence: Number.isFinite(confidence) ? Math.min(1, Math.max(0, confidence)) : 0,
  };
  // Lo que actúa sobre una orden existente necesita su número.
  if (['lab_order.move', 'lab_order.open', 'lab_order.update', 'lab_order.status', 'lab_order.edit'].includes(intent) && !result.order_id) result.intent = 'unknown';
  // Con una orden en creación solo vale corregirla; sin ella, draft_edit no tiene sentido.
  if (m.hasDraft ? !['lab_order.draft_edit', 'unknown'].includes(result.intent) : result.intent === 'lab_order.draft_edit') result.intent = 'unknown';
  if (result.intent === 'lab_order.draft_edit' && !result.draft_edit) result.intent = 'unknown';
  return result;
},
  perio: (p) => {
  // Solo comandos que el motor sabe correr, en rango. Confirmar, descartar y parar no.
  const int = (v, min, max) => { const n = Number(v); return v != null && v !== '' && Number.isInteger(n) && n >= min && n <= max ? n : undefined; };
  const tooth = v => { const n = int(v, 11, 48); return n != null && n % 10 >= 1 && n % 10 <= 8 ? n : undefined; };
  const oneOf = (list, v) => (list.includes(v) ? v : undefined);
  const sites = v => { if (!Array.isArray(v)) return undefined; const s = [...new Set(v.map(x => int(x, 0, 2)).filter(x => x != null))]; return s.length ? s : undefined; };
  const clean = o => Object.fromEntries(Object.entries(o).filter(([, v]) => v !== undefined));
  const one = c => {
    if (!c || typeof c !== 'object') return null;
